# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİN VE FELSEFENİN KAYNAK, YÖNTEM VE AMAÇ KARŞILAŞTIRMASI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Din (İlahi Vahiy Ekseni)</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Kaynağı: Yüce Allah\'ın gönderdiği Vahiy</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">ve Peygamberlerin sünnetidir; aklı dışlamaz.</text>\n  <text x="50" y="142" font-size="11" fill="#334155">• Yöntemi: İman, teslimiyet, ibadet, salih</text>\n  <text x="60" y="159" font-size="10.5" fill="#475569">amel ve vahiy ışığında tefekkürdür.</text>\n  <text x="50" y="181" font-size="11" fill="#334155">• Amacı: İnsanı dünya ve ahiret mutluluğuna</text>\n  <text x="60" y="198" font-size="10.5" fill="#475569">(felâh ve saadete) ulaştırmaktır.</text>\n  <text x="185" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Kesin, değişmez ve bağlayıcı inanç ilkeleri sunar</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Felsefe (İnsan Aklı Ekseni)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Kaynağı: İnsan aklı, mantıksal çıkarım,</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">merak, hayret ve eleştirel düşüncedir.</text>\n  <text x="380" y="142" font-size="11" fill="#334155">• Yöntemi: Sorgulama, şüphe, rasyonel</text>\n  <text x="390" y="159" font-size="10.5" fill="#475569">temellendirme ve kavramsal analizdir.</text>\n  <text x="380" y="181" font-size="11" fill="#334155">• Amacı: Varlık, bilgi ve değer alanında</text>\n  <text x="390" y="198" font-size="10.5" fill="#475569">hakikati aramak ve anlamlandırmaktır.</text>\n  <text x="515" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Öznel, kümülatif (yığılmalı) ve ucu açık sistemdir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİN VE FELSEFENİN ORTAK SORULARI: VARLIK, BİLGİ VE DEĞER</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ontoloji (Varlık Alanı)</text>\n  <text x="40" y="105" font-size="11" fill="#334155">• Evren nasıl var olmuştur?</text>\n  <text x="40" y="127" font-size="11" fill="#334155">• Varlığın ilk nedeni (arkhe)</text>\n  <text x="50" y="144" font-size="10.5" fill="#475569">ve Yaratıcısı kimdir?</text>\n  <text x="40" y="168" font-size="11" fill="#334155">• İnsanın evrendeki yeri ve</text>\n  <text x="50" y="185" font-size="10.5" fill="#475569">ölümden sonraki hayat nedir?</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Epistemoloji (Bilgi Alanı)</text>\n  <text x="262" y="105" font-size="11" fill="#334155">• Doğru bilgiye ulaşmak</text>\n  <text x="272" y="122" font-size="10.5" fill="#475569">mümkün müdür?</text>\n  <text x="262" y="146" font-size="11" fill="#334155">• Bilginin kaynakları nelerdir?</text>\n  <text x="262" y="168" font-size="10.5" fill="#475569">İslam\'da: Selim akıl, sağlam</text>\n  <text x="262" y="185" font-size="10.5" fill="#475569">duyular ve sadık haber (vahiy).</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Aksiyoloji (Değer ve Ahlak)</text>\n  <text x="485" y="105" font-size="11" fill="#334155">• İyi ve kötü nedir?</text>\n  <text x="485" y="127" font-size="11" fill="#334155">• İnsan eylemlerinde özgür ve</text>\n  <text x="495" y="144" font-size="10.5" fill="#475569">sorumlu mudur?</text>\n  <text x="485" y="168" font-size="11" fill="#334155">• Erdemli bir yaşam ve</text>\n  <text x="495" y="185" font-size="10.5" fill="#475569">mutluluk nasıl kazanılır?</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM DÜŞÜNCESİNDE HİKMET VE İSLAM FİLOZOFLARI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kur\'an\'da Akıl, Tefekkür ve Hikmet</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• &quot;Düşünmez misiniz?&quot;, &quot;Akletmez misiniz?&quot;</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">buyruklarıyla Kur\'an rasyonel düşünceyi emreder.</text>\n  <text x="50" y="143" font-size="11" fill="#334155">• Hikmet (Bakara, 269): Varlığın gayesini</text>\n  <text x="60" y="160" font-size="10.5" fill="#475569">ve eşyanın hakikatini kavrama bilgeliğidir.</text>\n  <text x="50" y="183" font-size="11" fill="#334155">• Beytülhikme (830): Tercüme ve felsefi</text>\n  <text x="60" y="200" font-size="10.5" fill="#475569">üretimin İslam medeniyetindeki merkezi.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Din-Felsefe Uzlaşısı (İslam Filozofları)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Kindî: İlk İslam filozofu; felsefe ile</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">vahiylerin aynı hakikati anlattığını savundu.</text>\n  <text x="380" y="142" font-size="11" fill="#334155">• Fârâbî (Muallim-i Sânî) &amp; İbn Sînâ:</text>\n  <text x="390" y="159" font-size="10.5" fill="#475569">Varlığı Zorunlu (Vâcib) ve Mümkün diye ayırdı.</text>\n  <text x="380" y="181" font-size="11" fill="#334155">• İbn Rüşd (Faslü\'l-Makâl): &quot;Hakikat hakikate</text>\n  <text x="390" y="198" font-size="10.5" fill="#475569">ters düşmez&quot; (Din ile felsefe sütkardeştir).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
